import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.Ce1WstT_.js";const m=JSON.parse('{"title":"4. Requirements","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/requirements.md","filePath":"getting-started/requirements.md"}'),i={name:"getting-started/requirements.md"};function r(s,e,l,c,u,d){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="_4-requirements" tabindex="-1">4. Requirements <a class="header-anchor" href="#_4-requirements" aria-label="Permalink to &quot;4. Requirements&quot;">​</a></h1><p>The project adheres strictly to the following functional and non-functional requirements.</p><h2 id="functional-requirements" tabindex="-1">Functional Requirements <a class="header-anchor" href="#functional-requirements" aria-label="Permalink to &quot;Functional Requirements&quot;">​</a></h2><ul><li><strong>Authentication</strong>: Users must be able to log in securely using seeded credentials and maintain a session via stateless JWTs.</li><li><strong>Role-Based Access Control (RBAC)</strong>: <ul><li><strong>ADMIN</strong>: Full access.</li><li><strong>SALES</strong>: CRM and Challan management, read-only catalog access.</li><li><strong>WAREHOUSE</strong>: Stock adjustments, read-only Challan and Catalog access.</li><li><strong>ACCOUNTS</strong>: Read-only access to all modules for auditing.</li></ul></li><li><strong>Customer Management</strong>: Ability to create, view, and update customer profiles with states (LEAD, ACTIVE, INACTIVE).</li><li><strong>Customer Follow-ups</strong>: Logging of text-based interaction notes and scheduling future contact dates.</li><li><strong>Product Management</strong>: Ability to manage a catalog of items with SKUs, Categories, and Unit Prices.</li><li><strong>Inventory</strong>: Display real-time stock balances and trigger low-stock alerts on dashboards.</li><li><strong>Stock Movements</strong>: Manual stock adjustments (IN/OUT) with reasons.</li><li><strong>Sales Challans</strong>: <ul><li>Create DRAFT challans assigning a customer and product items.</li><li>Snapshot product name, SKU, and price at the time of drafting.</li><li>CONFIRM challans to deduct stock.</li><li>CANCEL challans to void drafts or restock confirmed items.</li></ul></li><li><strong>Dashboard</strong>: Provide a top-level summary of operational metrics.</li></ul><h2 id="non-functional-requirements" tabindex="-1">Non-Functional Requirements <a class="header-anchor" href="#non-functional-requirements" aria-label="Permalink to &quot;Non-Functional Requirements&quot;">​</a></h2><ul><li><strong>Security</strong>: Prevent SQL injection via parameterized queries. Protect against XSS and CSRF (via proper header controls and local storage scoping). Provide rate-limiting on authentication routes.</li><li><strong>Performance</strong>: Use database indexes for fast query resolution. Implement TanStack Query caching on the frontend to reduce unnecessary network requests.</li><li><strong>Reliability</strong>: All stock deductions must occur within ACID-compliant PostgreSQL transactions.</li><li><strong>Maintainability</strong>: Follow Clean Architecture in the backend (Routes → Controllers → Services → Repositories).</li><li><strong>Responsive UI</strong>: The client application must render correctly on mobile, tablet, and desktop viewports.</li><li><strong>Concurrency Safety</strong>: Implement explicit row locking to prevent race conditions during order confirmations.</li></ul>',6)])])}const h=t(i,[["render",r]]);export{m as __pageData,h as default};
